import React, { useEffect, useState } from "react";
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import { Navigation } from "./components/navigation";
import { Header } from "./components/header";
import { About } from "./components/about";
import { About2 } from "./components/about2";
import { Features } from "./components/features";
import Login from "./components/login";
import Register from "./components/register";
import JsonData from "./data/data.json";
import "./App.css";
import ProfilePage from "./components/profile";
import Footer from "./components/footer";
import LandingPage from "./components/landing";
import Findavet from "./components/findavet";
import Shops from "./components/shops";
import PetShop from "./components/petshop";
import ShopProfile from "./components/shopprofile";
import OtpPage from "./components/otppage";
import VetLayout from "./components/VetLayout";
import VetDashboard from "./components/VetDashboard";
import VetAppointments from "./components/VetAppointments";
import VetHistory from "./components/VetHistory";

const App = () => {
  const [landingPageData, setLandingPageData] = useState({});
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  useEffect(() => {
    setLandingPageData(JsonData);
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);
  }, []);

  return (
    <Routes>
      {/* Pages with Navigation */}
      <Route
        path="/"
        element={
          <>
            <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
            <LandingPage />
          </>
        }
      />
      <Route
        path="/home"
        element={
          <>
            <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
            <Header data={landingPageData.Header} />
            <Features data={landingPageData.Features} />
            <About data={landingPageData.About} />
            <About2 data={landingPageData.About2} />
            <Footer data={landingPageData.Footer} />
          </>
        }
      />

      {/* Authentication */}
      <Route
        path="/login"
        element={
          <>
            <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
            <Login setIsLoggedIn={setIsLoggedIn} />
          </>
        }
      />
      <Route
        path="/register"
        element={
          <>
            <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
            <Register />
          </>
        }
      />

      {/* Other Pages */}
      <Route path="/findavet" element={<><Navigation /><Findavet /></>} />
      <Route path="/shops" element={<><Navigation /><Shops /></>} />
      <Route path="/petshop/:clinicId" element={<><Navigation /><PetShop /></>} />
      <Route path="/shopprofile/:clinicId" element={<><Navigation /><ShopProfile /></>} />
      <Route path="/otp" element={<><Navigation /><OtpPage /></>} />

      {/* Vet Dashboard */}
      <Route
        path="/clinic/*"
        element={
          <>
            <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
            <VetLayout />
          </>
        }
      >
        <Route path="dashboard" element={<VetDashboard />} />
        <Route path="appointments" element={<VetAppointments />} />
        <Route path="history" element={<VetHistory />} />
      </Route>

      {/* Profile */}
      <Route
        path="/profile"
        element={
          <>
            <Navigation isLoggedIn={isLoggedIn} setIsLoggedIn={setIsLoggedIn} />
            <ProfilePage />
          </>
        }
      />
    </Routes>
  );
};

// Wrap App in Router
const AppWrapper = () => (
  <Router>
    <App />
  </Router>
);

export default AppWrapper;
